(()=>{const e=document.querySelector(".opening-overlay");if(!e)return;const n=()=>{document.documentElement.classList.remove("opening-active"),e.remove()};if(document.documentElement.classList.contains("opening-seen")||window.matchMedia("(prefers-reduced-motion: reduce)").matches){n();return}try{sessionStorage.setItem("bharata-opening-logo-v2-seen","1")}catch{}e.addEventListener("animationend",t=>{t.target===e&&n()}),window.setTimeout(n,3500)})();
